def task_state(env) -> dict:
    """The task's own Python state (timers, previous positions, fixture flags), for the state hash."""
    skip = {"_obs_cache", "_ep_meta", "_cam_configs", "object_cfgs", "fixture_cfgs", "_curr_gen_fixtures"}
